type Shape =
	| { readonly kind: 'Circle'; readonly radius: number }
	| { readonly kind: 'Rectangle'; readonly width: number; readonly height: number }
	| { readonly kind: 'Triangle'; readonly base: number; readonly height: number };

function area(shape: Shape): number {
	switch (shape.kind) {
		case 'Circle':
			return Math.PI * shape.radius ** 2;
		case 'Rectangle':
			return shape.width * shape.height;
		case 'Triangle':
			return (shape.base * shape.height) / 2;
	}
}

const shapes: readonly Shape[] = [
	{ kind: 'Circle', radius: 1.5 },
	{ kind: 'Rectangle', width: 3, height: 4 },
	{ kind: 'Triangle', base: 6, height: 2.5 },
];

let total = 0;
for (const shape of shapes) {
	const shapeArea = area(shape);
	total += shapeArea;
	console.log(`${shape.kind}: ${shapeArea.toFixed(3)}`);
}
console.log(`Total: ${total.toFixed(3)} (${total})`);

export interface Point {
	readonly x: number;
	readonly y: number;
}

export function distance(from: Point, to: Point): number {
	return Math.sqrt((to.x - from.x) ** 2 + (to.y - from.y) ** 2);
}

export function pathLength(points: readonly Point[]): number {
	let length = 0;
	let previous: Point | undefined = undefined;
	for (const point of points) {
		if (previous !== undefined) {
			length += distance(previous, point);
		}
		previous = point;
	}
	return length;
}

class Stack<Item> {
	private readonly items: Item[] = [];

	push(item: Item): void {
		this.items.push(item);
	}

	pop(): Item | undefined {
		return this.items.pop();
	}

	size(): number {
		return this.items.length;
	}
}

const openers = new Map<string, string>([
	[')', '('],
	[']', '['],
	['}', '{'],
]);

function isBalanced(input: string): boolean {
	const stack = new Stack<string>();
	for (const character of input) {
		if (character === '(' || character === '[' || character === '{') {
			stack.push(character);
			continue;
		}
		const opener = openers.get(character);
		if (opener !== undefined && stack.pop() !== opener) {
			return false;
		}
	}
	return stack.size() === 0;
}

for (const input of ['([]{})', '([)]', '((', '', 'f(x[0]) { }']) {
	console.log(`'${input}' ${isBalanced(input) ? 'balanced' : 'unbalanced'}`);
}

